<script setup lang="ts">
import { friendlyError } from '@lostsky/api/client'; import LsButton from '@lostsky/ui/components/LsButton.vue'; import LsField from '@lostsky/ui/components/LsField.vue'; import LsInlineError from '@lostsky/ui/components/LsInlineError.vue'; import LsMarkdownEditor from '@lostsky/ui/components/LsMarkdownEditor.vue'; import LsPageHeader from '@lostsky/ui/components/LsPageHeader.vue'; import LsPanel from '@lostsky/ui/components/LsPanel.vue'; import LsUploadField from '@lostsky/ui/components/LsUploadField.vue'; import { feedback } from '@lostsky/ui/feedback'; import { useMutation,useQuery } from '@tanstack/vue-query'; import { NInput,NInputNumber,NSelect,NSwitch,useDialog } from 'naive-ui'; import { computed,reactive,watch } from 'vue'; import { useRoute,useRouter } from 'vue-router'; import { canManage,manageApi } from '../../lib'
const route=useRoute();const router=useRouter();const dialog=useDialog();const id=computed(()=>Number(route.params.id||0));const editing=computed(()=>id.value>0);const form=reactive({name:'',description:'',cover_image:'',introduction_markdown:'',price:0,cost:0,handler_cut:null as number|null,sender_cut:null as number|null,cs_cut:null as number|null,team_cut:null as number|null,entity_id:null as number|null,kind:1,benefit_package_id:null as number|null,redemption_campaign_id:null as number|null,is_active:1,handler_entity_ids:[] as number[]});const options=useQuery({queryKey:['manage-options'],queryFn:manageApi.options});const detail=useQuery({queryKey:computed(()=>['manage-product',id.value]),queryFn:()=>manageApi.product(id.value),enabled:editing});function kindNumber(value:unknown){if(typeof value==='number')return value;const mapped:{[key:string]:number}={'普通商品':1,'服务套餐':2,'权益卡密':3};return mapped[String(value)]??(Number(value)||1)}watch(()=>detail.data.value,d=>{if(d)Object.assign(form,d,{kind:kindNumber(d.kind),price:Number(d.price),cost:Number(d.cost),handler_cut:d.handler_cut==null?null:Number(d.handler_cut),sender_cut:d.sender_cut==null?null:Number(d.sender_cut),cs_cut:d.cs_cut==null?null:Number(d.cs_cut),team_cut:d.team_cut==null?null:Number(d.team_cut),handler_entity_ids:(d.handlers??[]).map((h:any)=>Number(h.entity_id))})},{immediate:true});const entities=computed(()=>(options.data.value?.entities??[]).map(e=>({label:e.name,value:Number(e.entity_id??e.id)})));const packages=computed(()=>(options.data.value?.packages??[]).map(p=>({label:p.name,value:p.id})));const campaigns=computed(()=>(options.data.value?.campaigns??[]).map(c=>({label:c.name,value:c.id})));watch(()=>form.kind,v=>{if(v!==2)form.benefit_package_id=null;if(v!==3)form.redemption_campaign_id=null});const save=useMutation({mutationFn:async()=>{const body={...form,description:form.description.trim()||null,introduction_markdown:form.introduction_markdown||null,entity_id:form.entity_id||null};const result=await manageApi.saveProduct(editing.value?id.value:null,body);const productId=editing.value?id.value:result.id;await manageApi.setProductHandlers(productId,form.handler_entity_ids);return {id:productId}},onSuccess:data=>{feedback.success('商品已保存');router.push(`/manage/products/${data.id}`)}});const disable=useMutation({mutationFn:()=>manageApi.disableProduct(id.value),onSuccess:()=>router.push('/manage/products')});function stop(){dialog.warning({title:'下架商品',content:'下架后前台不再展示，历史订单和已交付权益保持不变。',positiveText:'确认下架',negativeText:'返回',onPositiveClick:()=>disable.mutate()})}const valid=computed(()=>Boolean(form.name.trim()&&form.cover_image.trim()&&form.price>=0&&(form.kind!==2||form.benefit_package_id)&&(form.kind!==3||form.redemption_campaign_id)))
</script><template><div class="manage-page"><LsPageHeader :title="editing?'编辑商品':'新建商品'" description="商品类型决定订单完成时的履约结果；服务和卡密配置由后端再次校验。" back-to="/manage/products" back-label="返回商品"><template #actions><RouterLink v-if="editing" class="secondary-link" :to="`/manage/products/${id}/fields`">核销字段</RouterLink><a v-if="editing" class="secondary-link" :href="`/product/${id}`" target="_blank" rel="noopener noreferrer">预览前台</a><LsButton v-if="editing&&canManage('shop.product.delete')" variant="danger" @click="stop">下架商品</LsButton></template></LsPageHeader><form class="manage-form" @submit.prevent="save.mutate()"><LsPanel><div class="form-panel"><h2>基本信息</h2><LsField label="商品名称" for-id="product-name" required><NInput id="product-name" v-model:value="form.name" maxlength="100"/></LsField><LsField label="简短说明" for-id="product-description"><NInput id="product-description" v-model:value="form.description" type="textarea" maxlength="500" show-count/></LsField><LsField label="封面" for-id="product-cover" required hint="当前可填写已登记媒体的 URL。"><LsUploadField id="product-cover" v-model="form.cover_image" disabled disabled-reason="商城暂未配置直接上传入口，请粘贴已登记媒体 URL" show-reason/></LsField><LsField label="详情" for-id="product-markdown"><LsMarkdownEditor id="product-markdown" v-model="form.introduction_markdown" :draft-key="`shop-product-${id||'new'}`" upload-disabled-reason="商城详情暂未配置图片上传，请使用已登记媒体 URL"/></LsField><LsField label="上架状态" for-id="product-active"><NSwitch id="product-active" :value="form.is_active===1" @update:value="v=>form.is_active=v?1:0"/></LsField></div></LsPanel><LsPanel><div class="form-panel"><h2>销售与履约</h2><LsField label="商品类型" for-id="product-kind" required><NSelect id="product-kind" v-model:value="form.kind" :options="[{label:'普通商品',value:1},{label:'服务套餐',value:2},{label:'权益卡密',value:3}]"/></LsField><LsField v-if="form.kind===2" label="服务权益包" for-id="product-package" required><NSelect id="product-package" v-model:value="form.benefit_package_id" :options="packages" filterable/></LsField><LsField v-if="form.kind===3" label="卡密活动" for-id="product-campaign" required><NSelect id="product-campaign" v-model:value="form.redemption_campaign_id" :options="campaigns" filterable/></LsField><LsField label="售价" for-id="product-price" required><NInputNumber id="product-price" v-model:value="form.price" :min="0" :precision="2"/></LsField><LsField label="成本" for-id="product-cost"><NInputNumber id="product-cost" v-model:value="form.cost" :min="0" :precision="2"/></LsField><LsField label="专属 Entity" for-id="product-owner"><NSelect id="product-owner" v-model:value="form.entity_id" :options="entities" filterable clearable placeholder="留空表示团队公用商品"/></LsField><LsField label="可选接单人" for-id="product-handlers" hint="普通商品用于下单选择；服务商品的核销接单池由服务定义控制。"><NSelect id="product-handlers" v-model:value="form.handler_entity_ids" :options="entities" multiple filterable clearable/></LsField></div></LsPanel><LsPanel><div class="form-panel"><h2>默认分配</h2><p class="form-intro">留空时由服务端按商品规则补齐；填写的金额由订单创建时冻结。</p><LsField label="接单分配" for-id="product-handler-cut"><NInputNumber id="product-handler-cut" v-model:value="form.handler_cut" :min="0" :precision="2" clearable/></LsField><LsField label="发单分配" for-id="product-sender-cut"><NInputNumber id="product-sender-cut" v-model:value="form.sender_cut" :min="0" :precision="2" clearable/></LsField><LsField label="客服分配" for-id="product-cs-cut"><NInputNumber id="product-cs-cut" v-model:value="form.cs_cut" :min="0" :precision="2" clearable/></LsField><LsField label="团队分配" for-id="product-team-cut"><NInputNumber id="product-team-cut" v-model:value="form.team_cut" :min="0" :precision="2" clearable/></LsField></div></LsPanel><LsInlineError v-if="detail.isError.value" :message="friendlyError(detail.error.value)"/><LsInlineError v-if="save.isError.value" :message="friendlyError(save.error.value)"/><div class="form-actions"><LsButton type="button" variant="secondary" @click="router.back()">取消</LsButton><LsButton type="submit" :disabled="!valid||!canManage('shop.product.write')" :loading="save.isPending.value">保存商品</LsButton></div></form></div></template>
